13|/*
14| * We convert as.c into a header file to make convenient for fuzzing.
15| * We do this for several of the binutils applications when creating
16| * the binutils fuzzers.
17| */
18|#include <fuzz_as.h>
19|
20|int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);
21|int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
22|  char filename[256];
23|  sprintf(filename, "/tmp/libfuzzer-%d.s", getpid());
24|  FILE *fp = fopen(filename, "wb");
25|  if (!fp) {
26|    return 0;
27|  }
28|  fwrite(data, size, 1, fp);
29|  fclose(fp);
30|
31|  reg_section = NULL;
32|
33|  const char *fakeArgv[3];
34|  fakeArgv[0] = "fuzz_objdump";
35|  fakeArgv[1] = filename; // Assemble our fake source file.
36|  fakeArgv[2] = NULL;
37|
38|  out_file_name = "/tmp/tmp-out";
39|
40|  // as initialition. This follows the flow of ordinary main function
41|  symbol_begin ();
42|  frag_init ();
43|  subsegs_begin ();
44|  read_begin ();
45|  input_scrub_begin ();
46|  expr_begin ();
47|  macro_init (flag_macro_alternate, flag_mri, 0, macro_expr);
48|
49|  output_file_create (out_file_name);
50|  itbl_init ();
51|  dwarf2_init ();
52|  cond_finish_check (-1);
53|
54|  dot_symbol_init ();
55|
56|  // Main fuzzer target. Assemble our random data.
57|  perform_an_assembly_pass (2, (char**)fakeArgv);
58|
59|  // Cleanup
60|  cond_finish_check (-1);
61|  dwarf2_finish ();
62|  cfi_finish ();
63|  input_scrub_end ();
64|
65|  unlink(filename);
66|
67|  return 0;
68|}

