1797|#if ARCH(Intel) && WSIZE(32)
1798|  stat = (real_fclose) (stream);
1799|#else
1800|  stat = CALL_REAL (fclose)(stream);
1801|#endif
1802|  if (RECHCK_REENTRANCE (guard))
1803|    {
1804|      POP_REENTRANCE (guard);
