33|void
34|output_file_create (const char *name)
35|{
36|  if (name[0] == '-' && name[1] == '\0')
37|    as_fatal (_("can't open a bfd on stdout %s"), name);
38|
39|  else if (!(stdoutput = bfd_openw (name, TARGET_FORMAT)))
40|    {
41|      bfd_error_type err = bfd_get_error ();
42|
43|      if (err == bfd_error_invalid_target)
44|	as_fatal (_("selected target format '%s' unknown"), TARGET_FORMAT);
45|      else
46|	as_fatal (_("can't create %s: %s"), name, bfd_errmsg (err));
47|    }
48|
49|  bfd_set_format (stdoutput, bfd_object);
50|  bfd_set_arch_mach (stdoutput, TARGET_ARCH, TARGET_MACH);
51|  if (flag_traditional_format)
52|    stdoutput->flags |= BFD_TRADITIONAL_FORMAT;
53|}

252|void
253|itbl_init (void)
254|{
255|  struct itbl_entry *e, **es;
256|  e_processor procn;
257|  e_type type;
258|
259|  if (!itbl_have_entries)
260|    return;
261|
262|  /* Since register names don't have a prefix, put them in the symbol table so
263|     they can't be used as symbols.  This simplifies argument parsing as
264|     we can let gas parse registers for us.  */
265|  /* Use symbol_create instead of symbol_new so we don't try to
266|     output registers into the object file's symbol table.  */
267|
268|  for (type = e_regtype0; type < e_nregtypes; type++)
269|    for (procn = e_p0; procn < e_nprocs; procn++)
270|      {
271|	es = get_entries (procn, type);
272|	for (e = *es; e; e = e->next)
273|	  {
274|	    symbol_table_insert (symbol_create (e->name, reg_section,
275|						&zero_address_frag, e->value));
276|	  }
277|      }
278|  append_insns_as_macros ();
279|}

