1215|
1216|  /* Skip argv[0].  */
1217|  argv++;
1218|  argc--;
1219|
1220|  while (argc--)
1221|    {
1222|      if (*argv)
1223|	{			/* Is it a file-name argument?  */
1224|	  PROGRESS (1);
