288|static inline int
289|address_bytes (void)
290|{
291|  /* Choose smallest of 1, 2, 4, 8 bytes that is large enough to
292|     contain an address.  */
293|  int n = (stdoutput->arch_info->bits_per_address - 1) / 8;
294|  n |= n >> 1;
295|  n |= n >> 2;
296|  n += 1;
297|  return n;
